import { useEffect, useState } from 'react';
import type { BuiltContent, Dua } from './types';

/**
 * The content is its own chunk (dynamic import), not part of the main bundle.
 * It is generated by scripts/build-content.ts behind the review gate.
 */
let cache: BuiltContent | null = null;
let pending: Promise<BuiltContent> | null = null;

export function loadContent(): Promise<BuiltContent> {
  if (cache) return Promise.resolve(cache);
  pending ??= import('./generated/duas.json').then((m) => {
    cache = (m.default ?? m) as unknown as BuiltContent;
    return cache;
  });
  return pending;
}

export function useContent(): BuiltContent | null {
  const [content, setContent] = useState<BuiltContent | null>(cache);
  useEffect(() => {
    if (!content) void loadContent().then(setContent);
  }, [content]);
  return content;
}

export function findDua(content: BuiltContent, id: string): Dua | undefined {
  return content.duas.find((d) => d.id === id);
}

/** True when a card shown is below `verified` (only possible in preview builds). */
export function isDraftCard(dua: Dua): boolean {
  return dua.review.status !== 'verified' && dua.review.status !== 'approved';
}
